/* Financial & Business Education: 18 subjects. New lessons fill the gaps around the existing finance, strategy and entrepreneurship lessons,
   which stay where they are (same ids and saved progress) and are shown inside this category through FIN_REFS in learn.js.
   Add new subjects at the END of the list only (lesson ids depend on order). Rules, rates and thresholds are never stated as current:
   exercises tell the learner to look them up from the official source and note the date. All of it is education, not personal advice. */
LEARN.cat({
 id: "Financial & Business Education",
 name: "Financial & Business Education",
 blurb: "Personal finance, investing, tax, company finance and business thinking, building on your existing finance and strategy lessons with Indonesian examples.",
 subjects: [
  { k: "Financial Literacy and Personal Finance", les: [
   { lv: "B", m: 45, df: 1, t: "Money basics: income, expenses, accounts and goals",
     obj: ["Tell income, expenses, savings and net worth apart", "Describe the main account types: current, savings, deposits and e-wallets", "Write three SMART money goals with amounts and dates"],
     ex: "List every source of income and every regular expense from last month, using your bank and e-wallet history. Calculate what was left. Then write three SMART money goals, each with an amount, a date and a first step.",
     qa: [["What is net worth?", "Everything you own minus everything you owe, at a point in time."], ["What does SMART mean for a goal?", "Specific, Measurable, Achievable, Relevant and Time-bound."], ["Why separate needs from wants?", "It shows which spending can flex when income falls or goals need more money."]],
     src: "OJK Sikapi Uangmu financial education materials; Elizabeth Warren and Amelia Warren Tyagi, All Your Worth; Morgan Housel, The Psychology of Money" },
   { lv: "I", m: 60, df: 3, t: "Your money system: emergency fund, insurance and accounts",
     obj: ["Size an emergency fund from your essential monthly costs", "Explain what insurance covers and what national health coverage (BPJS) offers", "Set up separate accounts for bills, saving and goals"],
     ex: "Add up your essential monthly costs. Multiply by 3 and by 6 to get an emergency fund range, and use more if your income is irregular. Check what your health coverage includes. Sketch an account setup: bills, emergency fund, goals and spending.",
     qa: [["How is an emergency fund usually sized?", "As a number of months of essential expenses, commonly 3 to 6 months, and more when income is irregular."], ["What risks does insurance transfer?", "Large, unlikely losses such as serious illness, accident or death that savings alone could not cover."], ["Why keep an emergency fund in an easily accessible account?", "Emergencies need quick cash, so safety and access matter more than the highest return."]],
     src: "OJK Sikapi Uangmu materials; BPJS Kesehatan benefit guides; Morgan Housel, The Psychology of Money" },
   { lv: "A", m: 75, df: 4, t: "Financial planning: goals, trade-offs and an annual plan",
     obj: ["Rank goals by time horizon and importance", "Build a one-page financial plan with numbers and review dates", "Explain how life events change a plan"],
     ex: "Write a one-page plan: income, spending, saving rate, emergency fund target, debt plan, insurance check, investing plan and two big goals with amounts and dates. Set a review date every 6 months and list two events that would force a change.",
     qa: [["Why rank goals by time horizon?", "Short-term goals need safe, accessible money, while long-term goals can accept more risk and volatility."], ["What is a savings rate?", "The share of income that is saved or invested rather than spent."], ["Why review a financial plan regularly?", "Income, prices, family needs and goals change, so the plan must change with them."]],
     src: "CFP Board financial planning process overview; OJK Sikapi Uangmu materials; Vicki Robin, Your Money or Your Life" }
  ] },
  { k: "Compound Interest", les: [
   { lv: "B", m: 45, df: 2, t: "Compound interest and the rule of 72",
     obj: ["Explain simple versus compound interest", "Use the formula FV = PV x (1 + r)^n", "Use the rule of 72 to estimate doubling time"],
     ex: "Calculate Rp10 million at 6 percent for 10 years with simple interest and with yearly compounding. Then use the rule of 72 to estimate doubling time at 4, 6, 8 and 12 percent, and check one of them with the formula.",
     qa: [["What does Rp10 million grow to at 6 percent compounded yearly for 10 years?", "About Rp17.9 million, compared with Rp16 million using simple interest."], ["What is the rule of 72?", "A shortcut: years to double is about 72 divided by the annual interest rate in percent."], ["Why does compounding grow faster over time?", "Interest earns interest, so each year's growth is based on a larger balance."]],
     src: "Khan Academy Finance and capital markets; Brealey, Myers and Allen, Principles of Corporate Finance, time value chapters; OJK Sikapi Uangmu materials" },
   { lv: "A", m: 75, df: 4, t: "Compounding with contributions, real returns and fees",
     obj: ["Calculate the future value of regular contributions", "Convert nominal rates to effective annual rates", "Show how fees and inflation reduce long-run results"],
     ex: "In a spreadsheet, model Rp1 million per month for 10 years at 6 percent a year (0.5 percent a month). Then rerun it with a 1 percent annual fee and 4 percent inflation. Compare nominal and real end values and write what changed most.",
     qa: [["What is the future value of Rp1 million saved monthly for 10 years at 6 percent a year?", "About Rp164 million, of which Rp120 million is contributions and the rest is growth."], ["What is the effective annual rate of 12 percent compounded monthly?", "About 12.68 percent, because monthly compounding adds interest on interest within the year."], ["How much can a 1 percent yearly fee cut a 30 year result at a 6 percent gross return?", "Roughly a quarter of the final value, because the net return falls to about 5 percent and compounds for decades."]],
     src: "Brealey, Myers and Allen, Principles of Corporate Finance; John Bogle, The Little Book of Common Sense Investing; spreadsheet functions FV and EFFECT" }
  ] },
  { k: "Opportunity Cost", les: [
   { lv: "B", m: 45, df: 1, t: "Opportunity cost in everyday money choices",
     obj: ["Define opportunity cost as the next best alternative", "Apply it to a purchase, a trip and a use of time", "Explain why free things still have a cost"],
     ex: "Pick a purchase you are considering. Write what else the same money or time could do: save, invest at 6 percent for 10 years, pay off debt or buy something else. Compare and decide. For example, Rp5 million could grow to about Rp8.95 million.",
     qa: [["What is opportunity cost?", "The value of the next best alternative you give up when you make a choice."], ["What is the opportunity cost of spending Rp5 million today if it could earn 6 percent for 10 years?", "About Rp8.95 million of future value given up."], ["Why does a free seminar still have an opportunity cost?", "Your time and attention could have been used in another way."]],
     src: "Mankiw, Principles of Economics, chapter 1; Tim Harford, The Undercover Economist; Morgan Housel, The Psychology of Money" },
   { lv: "I", m: 60, df: 3, t: "Opportunity cost of time, skills and career choices",
     obj: ["Estimate the value of your time using an hourly rate", "Compare a course, a job or a side project using opportunity cost", "Spot sunk cost thinking in decisions"],
     ex: "Estimate what an hour of your time is worth in earnings or learning. Compare two options, for example a course versus extra work, listing money, time, skills gained and what you give up. Identify a sunk cost you are tempted to count and drop it.",
     qa: [["Why should sunk costs be ignored when choosing what to do next?", "They are already paid and cannot be recovered, so they do not change the future costs and benefits of each option."], ["How can you estimate the opportunity cost of an hour?", "By what you could earn or gain from the best other use of that hour."], ["Why does a degree cost more than its tuition?", "It also costs the income and experience given up while studying."]],
     src: "Mankiw, Principles of Economics, chapter 1; Daniel Kahneman, Thinking, Fast and Slow; Arkes and Blumer (1985) on the psychology of sunk cost" },
   { lv: "A", m: 75, df: 4, t: "Opportunity cost in investment appraisal and hurdle rates",
     obj: ["Explain a hurdle rate as the opportunity cost of capital", "Compare projects with different returns and risks", "Explain why risk-adjusted comparison matters"],
     ex: "A shop owner has Rp50 million: new equipment returning Rp9 million a year, or a government bond at an assumed 6.5 percent. Compute both returns, discuss the risk difference and set a hurdle rate. State what extra return you would need for the riskier choice.",
     qa: [["What is a hurdle rate?", "The minimum return a project must earn to be worth doing, based on what alternatives of similar risk offer."], ["Why compare a risky project with a safe bond?", "The safe return is the opportunity cost, so a risky project must offer enough extra return to compensate for its risk."], ["What is a risk premium?", "The extra expected return required for taking more risk than a safe alternative."]],
     src: "Brealey, Myers and Allen, Principles of Corporate Finance, opportunity cost of capital; Aswath Damodaran, Investment Valuation; Ministry of Finance (DJPPR) government bond information" }
  ] },
  { k: "Inflation and Purchasing Power", les: [
   { lv: "B", m: 45, df: 1, t: "Inflation and what your money buys",
     obj: ["Explain how inflation reduces purchasing power", "Calculate the value of money after inflation", "Compare your own price changes with official inflation"],
     ex: "Take Rp100,000 and 4 percent inflation. Compute its buying power after 5 and 10 years. Then list 5 prices you pay (rice, fuel, data, rent, transport) from 3 years ago and now, and compute your own price change.",
     qa: [["How much buying power does Rp100,000 keep after 10 years of 4 percent inflation?", "About Rp67,600 in today's terms."], ["What is purchasing power?", "The amount of goods and services a given amount of money can buy."], ["Why can your inflation differ from the official figure?", "You buy a different basket of goods than the average household used for the index."]],
     src: "BPS inflation publications; Bank Indonesia inflation pages; Mankiw, Principles of Economics, chapter 24" },
   { lv: "I", m: 60, df: 3, t: "Protecting purchasing power: real returns and inflation",
     obj: ["Calculate a real return from a nominal return and inflation", "Compare cash, deposits, bonds, gold, stocks and property against inflation", "Explain why holding only cash loses value over time"],
     ex: "Make a table of 5 assets with an example nominal return and your assumed inflation. Compute real returns with the exact formula and mark which beat inflation. Note risk, liquidity and costs for each. Do not treat the example returns as forecasts.",
     qa: [["How do you calculate a real return?", "Divide 1 plus the nominal return by 1 plus inflation, then subtract 1."], ["What is the real return on a 6 percent deposit when inflation is 4 percent?", "About 1.9 percent, because 1.06 divided by 1.04 minus 1 is 0.019."], ["Why can an asset that beats inflation still be a poor choice?", "It may carry too much risk, be hard to sell or have high costs for your goals and time horizon."]],
     src: "Brealey, Myers and Allen, Principles of Corporate Finance; Jeremy Siegel, Stocks for the Long Run; Ministry of Finance (DJPPR) and Bank Indonesia pages for current rates" },
   { lv: "A", m: 75, df: 4, t: "Inflation, currency risk and long-term planning in Indonesia",
     obj: ["Explain how the rupiah exchange rate and imported goods link to prices", "Plan long-term goals with an inflation assumption and a range", "Evaluate protecting against currency risk and its costs"],
     ex: "Plan a goal 10 years away, such as a child's education or a house deposit, using three inflation assumptions (low, base, high). Show the target amount and the monthly saving needed in each case. Note which goals have costs in foreign currency. Use dated sources.",
     qa: [["Why does a weaker rupiah often raise some prices?", "Imported goods, materials and fuel cost more in rupiah, and firms pass part of this on to buyers."], ["Why use several inflation scenarios in a long-term plan?", "Future inflation is uncertain, so a range shows how sensitive the plan is."], ["Which goals may have costs in foreign currency?", "Overseas study, travel, imported equipment or some insurance and investment products."]],
     src: "Bank Indonesia inflation and exchange rate reports; BPS education and price data; IMF Article IV reports for Indonesia" }
  ] },
  { k: "Cash Flow Management", les: [
   { lv: "B", m: 45, df: 1, t: "Personal cash flow: income timing and the monthly cycle",
     obj: ["Tell cash flow from profit and from savings", "Map when money comes in and goes out during a month", "Find gaps between income and bills"],
     ex: "Make a calendar of one month showing paydays and due dates for rent, transport, data, installments and school fees. Mark the days when your balance would be lowest. Choose two bills to move or two actions to smooth the gap.",
     qa: [["What is cash flow?", "The movement of money in and out over time."], ["Why can you earn a salary and still run out of cash?", "The timing of bills and income may not match, so cash arrives later than it is needed."], ["What helps smooth personal cash flow?", "Aligning due dates with paydays, keeping a buffer and spreading big bills across months."]],
     src: "OJK Sikapi Uangmu materials; Morgan Housel, The Psychology of Money; Khan Academy personal finance" },
   { lv: "I", m: 60, df: 3, t: "Cash flow forecasting and buffers for irregular income",
     obj: ["Build a 12 week cash forecast", "Use a baseline and a buffer for variable income", "Set rules for good months and lean months"],
     ex: "Build a 12 week forecast in a spreadsheet: expected income in low, base and high cases against fixed costs. Set a rule such as: in good weeks, put half of the extra into a buffer. Test the rule on last quarter's real numbers.",
     qa: [["Why use low, base and high cases for irregular income?", "They show whether you can pay fixed costs in a weak period and how much buffer is needed."], ["What is a cash buffer?", "Money kept aside to cover bills when income is late or lower than expected."], ["What is an income smoothing rule?", "A rule that sets a steady personal pay from variable income, putting extra into a buffer in good months."]],
     src: "Jonathan Morduch and Rachel Schneider, The Financial Diaries; OJK Sikapi Uangmu materials; Morgan Housel, The Psychology of Money" },
   { lv: "A", m: 75, df: 4, t: "Business cash flow: working capital and the cash conversion cycle",
     obj: ["Explain working capital and why growth can drain cash", "Calculate days inventory, days receivable and days payable", "Calculate and improve the cash conversion cycle"],
     ex: "Use a small business example: inventory 40 days, receivables 30 days, payables 20 days. Compute the cash conversion cycle, then list three actions to shorten it, such as faster collection, lower stock or better payment terms.",
     qa: [["What is the cash conversion cycle?", "The days between paying for inventory and collecting cash from customers: days inventory plus days receivable minus days payable."], ["What is the cycle for 40 days of inventory, 30 days of receivables and 20 days of payables?", "50 days, because 40 plus 30 minus 20 equals 50."], ["Why can a fast-growing business run out of cash?", "It must pay suppliers and staff before customers pay, so growth ties up more working capital."]],
     src: "Brealey, Myers and Allen, Principles of Corporate Finance, working capital chapters; Aswath Damodaran, Applied Corporate Finance; IAI standards (PSAK) on cash flow statements" }
  ] },
  { k: "Assets vs. Liabilities", les: [
   { lv: "B", m: 45, df: 1, t: "Assets, liabilities and net worth",
     obj: ["Define assets, liabilities and net worth", "Sort your own items into assets and liabilities", "Explain why an asset is not always valuable"],
     ex: "Build a personal balance sheet: list what you own with estimated values and what you owe. Compute net worth. Mark each asset as liquid or illiquid and each liability by interest rate. Note anything that loses value over time.",
     qa: [["What is the basic equation for net worth?", "Assets minus liabilities."], ["Is a car an asset or a liability?", "It is an asset if you own it, but it usually loses value and costs money to run, so it may not build wealth."], ["What makes an asset liquid?", "It can be turned into cash quickly at close to its fair value."]],
     src: "Thomas Stanley and William Danko, The Millionaire Next Door; OJK Sikapi Uangmu materials; Khan Academy personal finance" },
   { lv: "I", m: 60, df: 3, t: "Good debt, bad debt and the quality of assets",
     obj: ["Judge debt by its interest rate, purpose and risk", "Rate assets by liquidity, income, growth potential and risk", "Explain why net worth and cash flow both matter"],
     ex: "List each debt with its balance, rate and purpose. Mark whether it funds something that grows, holds value or loses value. Then rank each asset by liquidity, income and risk. Write one change that improves net worth and one that improves cash flow.",
     qa: [["What makes debt riskier?", "A high or variable interest rate, funding something that loses value, or payments that strain cash flow."], ["Why is a mortgage often treated differently from credit card debt?", "It is usually cheaper and secured by an asset that may hold value, while card debt is costly and unsecured."], ["Why look at net worth and cash flow together?", "You can have high net worth but little cash, or good cash flow but little net worth, and both can cause problems."]],
     src: "Brealey, Myers and Allen, Principles of Corporate Finance; OJK Sikapi Uangmu materials; Thomas Stanley and William Danko, The Millionaire Next Door" },
   { lv: "A", m: 75, df: 4, t: "A personal balance sheet that you track every quarter",
     obj: ["Build a net worth tracker in a spreadsheet", "Track changes: contributions, growth and debt payments", "Interpret trends and set a next-quarter action"],
     ex: "Create a quarterly tracker: assets, liabilities, net worth and a simple breakdown of the change into new savings, investment growth and debt reduction. Fill in this quarter and set one action for the next. Keep it private and backed up.",
     qa: [["Why track net worth every quarter instead of every day?", "Short-term market moves are mostly noise, and a regular review shows the trend without causing stress or overreaction."], ["What are the three drivers of a change in net worth?", "New savings, growth or loss on investments and changes in debt."], ["Why record how you valued each asset?", "So that a change in your estimate is not mistaken for a real gain or loss."]],
     src: "Morgan Housel, The Psychology of Money; Vicki Robin, Your Money or Your Life; CFP Board planning resources" }
  ] },
  { k: "Budgeting, Saving and Debt Management", les: [
   { lv: "B", m: 60, df: 2, t: "Build a monthly budget that you can keep",
     obj: ["Create a zero-based or percentage budget", "Track spending for a month and sort it into categories", "Adjust the budget after the first month"],
     ex: "Track every expense for one month. Then build a budget using the 50, 30, 20 idea as a starting guide (needs, wants, saving and debt), adjusted to your life. At month end compare plan and actual and change two categories.",
     qa: [["What is a zero-based budget?", "A budget where every rupiah of income is assigned a purpose, so income minus planned spending and saving is zero."], ["What is the 50, 30, 20 guideline?", "A starting rule of thumb: about 50 percent of after-tax income to needs, 30 percent to wants and 20 percent to saving and debt payments."], ["Why review a budget after the first month?", "Real spending usually differs from the plan, and adjusting makes the budget realistic."]],
     src: "Elizabeth Warren and Amelia Warren Tyagi, All Your Worth; Ramit Sethi, I Will Teach You to Be Rich; OJK Sikapi Uangmu materials" },
   { lv: "I", m: 60, df: 3, t: "Saving systems and paying down debt: avalanche and snowball",
     obj: ["Automate saving by paying yourself first", "Compare the avalanche and snowball methods", "Calculate the interest cost of a debt and its payoff time"],
     ex: "List your debts. Plan payoff with the avalanche (highest rate first) and with the snowball (smallest balance first) and compare total interest and time in a spreadsheet. Set an automatic transfer to saving on payday.",
     qa: [["What is the avalanche method of paying debt?", "Pay minimums on all debts and put extra money on the debt with the highest interest rate first."], ["What is the snowball method of paying debt?", "Pay minimums on all debts and put extra money on the smallest balance first for quick wins."], ["Why pay yourself first?", "Moving money to saving as soon as you are paid makes saving automatic instead of depending on what is left over."]],
     src: "Ramit Sethi, I Will Teach You to Be Rich; Khan Academy personal finance; OJK Sikapi Uangmu materials" },
   { lv: "A", m: 75, df: 4, t: "Debt in Indonesia: credit cards, paylater, online loans and mortgages",
     obj: ["Compare the true cost of credit cards, paylater, online loans and mortgages", "Check whether a lender is licensed and read the contract", "Explain credit history (SLIK) and consumer protections"],
     ex: "Choose two credit products you have seen advertised. List the stated rate, fees, late charges and total cost of a Rp5 million loan over 6 months. Check whether the lender is registered with OJK. Note what you would check in the contract.",
     qa: [["Why can a loan with a low monthly rate still be expensive?", "Fees, flat-rate calculations and late charges can make the effective annual cost much higher than it first looks."], ["What is SLIK in Indonesian lending?","OJK's financial information system that records credit history, which lenders use to assess borrowers."], ["How can you check whether an online lender is legal?", "Check that it is registered or licensed with OJK before borrowing, and be wary of lenders that ask for access to your contacts or photos."]],
     src: "OJK consumer protection pages and lists of licensed lenders; OJK Sikapi Uangmu materials; Bank Indonesia consumer information" }
  ] },
  { k: "Behavioral Finance", les: [
   { lv: "B", m: 45, df: 1, t: "Money biases: loss aversion, FOMO and herding",
     obj: ["Describe loss aversion, FOMO and herding in money decisions", "Spot these biases in your own past choices", "Name one simple defense for each"],
     ex: "Recall one money decision driven by fear of missing out or by following others. Write what happened, which bias was involved and what rule would have helped, such as waiting 48 hours before buying.",
     qa: [["What is loss aversion?", "Feeling losses more strongly than equal gains, which can lead to avoiding risk or holding losing positions."], ["What is FOMO in investing?", "Fear of missing out, which pushes people to buy after prices have already risen."], ["What simple rule can reduce impulse decisions?", "A waiting period, such as 48 hours, before any non-essential purchase or investment."]],
     src: "Daniel Kahneman, Thinking, Fast and Slow; Morgan Housel, The Psychology of Money; Richard Thaler, Misbehaving" },
   { lv: "I", m: 60, df: 3, t: "Mental accounting, overconfidence and the disposition effect",
     obj: ["Explain mental accounting and overconfidence", "Describe the disposition effect", "Test your own habits with a decision log"],
     ex: "Keep a decision log for two weeks: each money decision, your reason, your confidence from 0 to 100 and the outcome. Then review where confidence was high and the result was poor, and name the bias.",
     qa: [["What is mental accounting?", "Treating money differently depending on its source or label, such as spending a bonus more freely than salary."], ["What is the disposition effect?", "The tendency to sell winners too early and hold losers too long."], ["Why is overconfidence costly for investors?", "It can lead to too much trading, too little diversification and underestimating risk."]],
     src: "Shefrin and Statman (1985) on the disposition effect; Terrance Odean (1998) Are investors reluctant to realize their losses?; Richard Thaler, Misbehaving" },
   { lv: "A", m: 75, df: 4, t: "Rules against bias: pre-commitment, checklists and decision logs",
     obj: ["Design an investment policy with rules set in advance", "Use pre-commitment, checklists and cooling-off periods", "Review decisions by process quality, not only by outcome"],
     ex: "Write a one-page personal money rulebook: what you will buy, when you will sell or rebalance, how much risk you accept and a cooling-off rule. Add a pre-purchase checklist. Review two past decisions by process, not only by result.",
     qa: [["What is pre-commitment in money decisions?", "Setting rules or automatic actions in advance so that emotions in the moment cannot easily change the plan."], ["Why judge decisions by process and not only outcomes?", "Good decisions can have bad outcomes through luck, and bad decisions can work out by luck."], ["What is a checklist useful for in investing?", "It forces key questions each time, such as purpose, risk, cost and alternatives, before acting."]],
     src: "Atul Gawande, The Checklist Manifesto; Annie Duke, Thinking in Bets; Morgan Housel, The Psychology of Money" }
  ] },
  { k: "Tax Structures and Tax Planning", les: [
   { lv: "B", m: 45, df: 1, t: "How taxes work: income tax, VAT and the annual return",
     obj: ["Tell income tax, value-added tax and other tax types apart", "Explain progressive and flat taxes", "Describe the NPWP, withholding and the annual tax return (SPT)"],
     ex: "Look up the current income tax brackets and the non-taxable income threshold (PTKP) on the Directorate General of Taxes website, and write them down with the date you checked. Then calculate the tax for an example income of Rp100 million a year.",
     qa: [["What is the difference between a progressive and a flat tax?", "A progressive tax takes a higher rate from higher income bands, while a flat tax uses one rate."], ["What is an NPWP?", "A taxpayer identification number used to register and report taxes in Indonesia."], ["What is the SPT?", "The annual tax return that taxpayers file to report income, tax paid and any tax due or refundable."]],
     src: "Directorate General of Taxes (DJP) website and tax guides; Law on Harmonization of Tax Regulations (UU HPP); OJK Sikapi Uangmu materials" },
   { lv: "I", m: 60, df: 3, t: "Employee, freelancer and small business taxes and records",
     obj: ["Tell employee, freelancer and business owner tax treatment apart", "Explain withholding, final tax and deductions", "Set up a simple record system for income and expenses"],
     ex: "Create a monthly records sheet: date, income, source, expenses, receipts and tax withheld. Fill in the last 3 months. Check on the Directorate General of Taxes site how your type of income is taxed and whether a final tax applies. Note the date you checked.",
     qa: [["What is withholding tax?", "Tax deducted from a payment by the payer, such as an employer, and paid to the tax office on your behalf."], ["What is a final tax?", "A tax that settles the liability on a certain income, so it does not need to be added again to ordinary income."], ["Why keep receipts and invoices?", "They support deductions and show your income and expenses if the tax office asks."]],
     src: "Directorate General of Taxes (DJP) guides on PPh 21 and small business tax; regulations on MSME final tax; a licensed tax consultant (konsultan pajak) for personal cases" },
   { lv: "A", m: 75, df: 4, t: "Tax planning: legal methods, timing, structures and limits",
     obj: ["Tell tax avoidance within the law from tax evasion", "Explain deductions, credits, timing and legal form as planning tools", "Judge when to ask a licensed tax consultant"],
     ex: "List five legal ways a person or small business can lower tax, such as claiming allowed deductions, timing income and expenses, choosing the right legal form or using tax incentives. For each, note the rule to check and the risk. Mark what needs a licensed consultant.",
     qa: [["What is the difference between tax avoidance and tax evasion?", "Avoidance uses the rules to reduce tax legally. Evasion hides income or breaks the rules and is illegal."], ["What is a tax credit compared with a deduction?", "A credit reduces the tax owed directly, while a deduction reduces the income on which tax is calculated."], ["Why should tax planning rely on current rules and professional advice?", "Tax rules change and depend on your situation, so check current law and ask a licensed consultant before acting."]],
     src: "Directorate General of Taxes (DJP) regulations; OECD tax policy studies; licensed tax consultants" }
  ] },
  { k: "Investing Fundamentals", les: [
   { lv: "B", m: 45, df: 1, t: "What investing is: return, risk and time horizon",
     obj: ["Define investing and tell it from saving and speculating", "Explain the link between risk and expected return", "Match time horizon to type of investment"],
     ex: "Write three goals with a time horizon each: under 1 year, 1 to 5 years and over 5 years. For each, list which kind of asset might fit, such as deposits, government bonds, funds or stocks, and why. This is practice, not a recommendation.",
     qa: [["What is the difference between saving and investing?", "Saving keeps money safe and accessible, while investing accepts risk for a higher expected return over time."], ["Why do higher expected returns come with higher risk?", "Investors need extra reward to accept uncertainty, and an asset with high returns and no risk would be bought until its price removed the advantage."], ["Why does time horizon matter when investing?", "Short horizons leave little time to recover from falls, so risky assets suit longer goals better."]],
     src: "Benjamin Graham, The Intelligent Investor; John Bogle, The Little Book of Common Sense Investing; OJK Sikapi Uangmu investment materials" },
   { lv: "I", m: 60, df: 3, t: "Asset classes: cash, bonds, stocks, gold and property",
     obj: ["Describe the main asset classes and their sources of return", "Compare risk, liquidity and costs of each", "Explain how each behaves in inflation and in recessions"],
     ex: "Make a table of cash and deposits, government bonds, stocks, gold and property: source of return, main risks, liquidity, typical costs and how each behaved in 1998 and 2020, using a reputable data source. Note the data years.",
     qa: [["What are the main sources of return from stocks?", "Dividends and growth in the share price, which comes from company profits growing."], ["Why is property considered illiquid?", "It takes time and costs to sell, and its price may not be easy to know."], ["Why do investors hold gold?", "It does not depend on a company or a government and has sometimes held value when other assets fell, though it pays no income and its price can be volatile."]],
     src: "Jeremy Siegel, Stocks for the Long Run; World Gold Council research; Indonesia Stock Exchange (IDX) statistics; Ministry of Finance (DJPPR) bond data" },
   { lv: "A", m: 75, df: 4, t: "Evidence-based investing: costs, skill versus luck and efficiency",
     obj: ["Explain the efficient market hypothesis and its critiques", "Show how costs affect long-run returns", "Review evidence on active versus index investing"],
     ex: "Read a recent SPIVA scorecard summary and write what share of active funds beat their benchmark over 10 years in one category, with the date. Then calculate the effect of a 1.5 percent versus a 0.2 percent annual fee on Rp100 million over 20 years at 7 percent gross.",
     qa: [["What does the efficient market hypothesis claim?", "That prices already reflect available information, so it is hard to beat the market consistently after costs."], ["What is the end value of Rp100 million over 20 years at 7 percent gross, with a 0.2 percent fee versus a 1.5 percent fee?", "About Rp373 million versus about Rp292 million, a difference of roughly Rp81 million."], ["What do SPIVA reports typically show?", "That a majority of actively managed funds in many markets and categories underperform their benchmark over long periods."]],
     src: "S&P Dow Jones Indices SPIVA scorecards; Burton Malkiel, A Random Walk Down Wall Street; Charles Ellis, Winning the Loser's Game; John Bogle, The Little Book of Common Sense Investing" }
  ] },
  { k: "Stocks, Bonds, ETFs and Dividends", les: [
   { lv: "B", m: 60, df: 2, t: "Stocks, bonds and funds explained: IDX, SBN and mutual funds",
     obj: ["Explain what a share, a bond and a fund are", "Name Indonesian examples: IDX stocks, government bonds (SBN) and mutual funds (reksa dana)", "Check whether a product and a seller are regulated by OJK"],
     ex: "Look up one example of each from official or exchange sources: a share, a government bond (SBN) and a mutual fund. Write who issues it, how it earns, the main risk, the minimum purchase and how to sell it. Check that the platform is registered with OJK.",
     qa: [["What is a bond?", "A loan to a government or company that pays interest and returns the principal at maturity."], ["What is a mutual fund (reksa dana)?", "A pool of money from many investors, managed professionally and invested in assets such as bonds or stocks."], ["What is a share of stock?", "A unit of ownership in a company, which may earn dividends and gain or lose value."]],
     src: "Indonesia Stock Exchange (IDX) education pages; Ministry of Finance (DJPPR) SBN information; OJK Sikapi Uangmu investment materials" },
   { lv: "I", m: 60, df: 3, t: "ETFs, index funds, dividends and how to compare them",
     obj: ["Explain ETFs, index funds and active funds", "Calculate dividend yield and the payout ratio", "Compare funds by cost, index, tracking and liquidity"],
     ex: "Pick two funds or ETFs that track a similar index and compare expense ratio, index, size, trading volume and past tracking difference from their fact sheets. Compute the dividend yield for one stock: yearly dividend per share divided by price.",
     qa: [["What is the dividend yield?", "Annual dividend per share divided by the share price, usually shown as a percentage."], ["What is the difference between an ETF and a traditional mutual fund?", "An ETF trades on an exchange during the day like a share, while a traditional fund is bought and sold at its end-of-day value."], ["What does an expense ratio show?", "The yearly cost of running a fund, as a percentage of the money invested."]],
     src: "Fund and ETF fact sheets from asset managers and IDX; John Bogle, The Little Book of Common Sense Investing; OJK Sikapi Uangmu investment materials" },
   { lv: "A", m: 75, df: 4, t: "Bond math and dividend analysis: yield, duration, sustainability",
     obj: ["Explain why bond prices and yields move in opposite directions", "Describe duration and credit risk", "Judge whether a dividend is sustainable"],
     ex: "Take a bond with a 6 percent coupon and 5 years left. Compute its price if market yields rise to 7 percent and fall to 5 percent, using a spreadsheet PRICE function. Then check one company's dividend: payout ratio, free cash flow and debt.",
     qa: [["Why do bond prices fall when market yields rise?", "New bonds pay more, so older bonds with lower coupons must sell at a lower price to give buyers a competitive yield."], ["What is duration in bond investing?", "A measure of how sensitive a bond's price is to changes in interest rates, roughly the weighted average time to receive its cash flows."], ["Why check free cash flow when judging a dividend?", "Dividends are paid from cash, so a dividend larger than free cash flow may not be sustainable."]],
     src: "Frank Fabozzi, Bond Markets, Analysis and Strategies; Aswath Damodaran, Investment Valuation; company annual reports on IDX" }
  ] },
  { k: "Portfolio Management and Risk Management", les: [
   { lv: "B", m: 45, df: 2, t: "Diversification and asset allocation basics",
     obj: ["Explain diversification and why it lowers risk", "Describe asset allocation across stocks, bonds and cash", "Explain risk tolerance versus risk capacity"],
     ex: "Write an example allocation for a long-term goal and a short-term goal, as percentages across stocks, bonds and cash. For each, give your reason and the fall in value you could stand without selling in panic. This is an exercise, not advice.",
     qa: [["What is diversification?", "Spreading money across different assets so that one poor result does not sink the whole portfolio."], ["What is asset allocation?", "How a portfolio is divided among asset classes such as stocks, bonds, cash and gold."], ["What is the difference between risk tolerance and risk capacity?", "Tolerance is how much loss you can stand emotionally. Capacity is how much loss your finances and goals can absorb."]],
     src: "Harry Markowitz (1952) Portfolio Selection; John Bogle, The Little Book of Common Sense Investing; OJK Sikapi Uangmu investment materials" },
   { lv: "I", m: 60, df: 3, t: "Risk measures, rebalancing and drawdowns",
     obj: ["Explain volatility, maximum drawdown and the Sharpe ratio", "Rebalance by calendar or by threshold", "Describe the gain needed to recover after a loss"],
     ex: "Take monthly returns for one fund over 5 years from its fact sheet. Compute the average, the standard deviation and the worst fall from a peak. Then compute what gain is needed to recover from a 20 percent and from a 50 percent loss.",
     qa: [["What gain is needed to recover from a 50 percent loss?", "100 percent, because the remaining half must double."], ["What is a maximum drawdown?", "The largest fall from a peak to a later low in a period."], ["What does rebalancing do?", "It returns a portfolio to its target mix by selling what grew and buying what fell, which keeps risk in line with the plan."]],
     src: "William Sharpe (1966) Mutual Fund Performance; Investopedia explanations of drawdown and rebalancing; John Bogle, The Little Book of Common Sense Investing" },
   { lv: "A", m: 75, df: 4, t: "Portfolio construction: correlation, risk budgets and stress tests",
     obj: ["Explain correlation and how it changes in crises", "Build a simple portfolio and test it against historical stress periods", "Write an investment policy statement"],
     ex: "Using a spreadsheet and public price data, combine two or three assets and compare risk with each alone. Stress test against 1998, 2008 and 2020 if data allows. Write an investment policy statement: goals, allocation, rebalancing rule, limits and review dates.",
     qa: [["Why can diversification disappoint in a crisis?", "Correlations between assets often rise in crises, so assets that normally move differently may fall together."], ["What is an investment policy statement?", "A written plan setting goals, risk limits, allocation, rebalancing rules and review dates, used to guide decisions."], ["What does a stress test do?", "It checks how a portfolio would have performed in past or imagined extreme conditions."]],
     src: "Harry Markowitz (1952) Portfolio Selection; Brinson, Hood and Beebower (1986) on asset allocation; CFA Institute portfolio management curriculum" }
  ] },
  { k: "Financial Statements and Company Valuation", les: [
   { lv: "B", m: 60, df: 2, t: "Reading an annual report and the IDX filings",
     obj: ["Find the main parts of an annual report", "Locate the financial statements and the notes", "Read the auditor's opinion and know what it means"],
     ex: "Download the latest annual report of one IDX-listed company from its investor page or the IDX website. Write down: the business description, revenue, net profit, total assets, total debt, the auditor's opinion and two risks named by management.",
     qa: [["What does an unqualified auditor's opinion mean?", "The auditor found the financial statements fairly presented in all material respects, which is not a guarantee of future performance."], ["Why are the notes to the financial statements important?", "They explain accounting policies and give details the statements alone do not show, such as debt terms and risks."], ["Which Indonesian standards govern financial reporting?", "The PSAK standards issued by the Indonesian Institute of Accountants (IAI), which follow international standards."]],
     src: "IDX company disclosures and annual reports; Indonesian Institute of Accountants (IAI) PSAK; OJK rules on listed company reporting" },
   { lv: "I", m: 75, df: 3, t: "Quality of earnings, cash conversion and accounting red flags",
     obj: ["Compare net income with operating cash flow", "Spot warning signs: rising receivables, one-off gains and aggressive accounting", "Read footnotes for debt, leases and related-party items"],
     ex: "For one listed company, compare 3 years of net profit with operating cash flow, and receivables growth with revenue growth. Note any gap, one-off gain or related-party transaction. Write whether earnings look high quality, with your reasons and limits.",
     qa: [["Why compare net income with operating cash flow?", "Profit can include non-cash items, so persistent profit without cash may signal low earnings quality."], ["What can receivables rising faster than revenue signal?", "Customers may be paying slowly, or revenue may be recognised too aggressively."], ["What is a related-party transaction?", "A deal between a company and its owners, directors or affiliated firms, which needs extra scrutiny for fairness."]],
     src: "Howard Schilit, Financial Shenanigans; Aswath Damodaran, The Little Book of Valuation; company annual reports on IDX" },
   { lv: "A", m: 75, df: 4, t: "Valuation in practice: scenarios, sensitivity and sanity checks",
     obj: ["Build a simple DCF with base, low and high scenarios", "Run a sensitivity table on growth and discount rate", "Cross-check with multiples and explain the limits"],
     ex: "Build a spreadsheet valuation for one company with three scenarios. Create a sensitivity table for discount rate and long-term growth. Compare the result with peers' price to earnings. Write the range, the biggest assumption and why the answer is not a precise number.",
     qa: [["Why use a sensitivity table in a valuation?", "Small changes in discount rate or growth can change value a lot, and a table shows how fragile the result is."], ["What is the terminal value in a DCF?", "The value of cash flows beyond the explicit forecast period, often a large part of the total value."], ["Why cross-check a DCF with multiples?", "It tests whether the DCF result is reasonable compared with how the market prices similar companies."]],
     src: "Aswath Damodaran, Investment Valuation and The Little Book of Valuation; CFA Institute equity valuation materials; company filings on IDX" }
  ] },
  { k: "Economics of Business", les: [
   { lv: "B", m: 60, df: 2, t: "Revenue, costs and margins of a small business",
     obj: ["Tell fixed from variable costs", "Calculate gross margin, operating margin and break-even", "Explain how price and volume change profit"],
     ex: "Pick a small business such as a food stall or a delivery service. Estimate price, variable cost per unit and monthly fixed costs. Calculate gross margin, break-even units and profit at 50, 100 and 200 units. Note which cost you could change most easily.",
     qa: [["How do you calculate break-even units?", "Fixed costs divided by the contribution margin per unit, which is price minus variable cost."], ["What is gross margin?", "Revenue minus the direct cost of goods sold, as a share of revenue."], ["What is a fixed cost?", "A cost that does not change with sales volume in the short run, such as rent."]],
     src: "Brealey, Myers and Allen, Principles of Corporate Finance, basics; Eric Ries, The Lean Startup; Steve Blank and Bob Dorf, The Startup Owner's Manual" },
   { lv: "A", m: 75, df: 4, t: "Pricing power, economies of scale and competitive dynamics",
     obj: ["Explain economies of scale and learning curves", "Describe network effects and switching costs", "Judge when a business can raise prices"],
     ex: "Choose one company or product you use, such as a ride app, a bank or a local shop chain. Write whether it benefits from scale, network effects or switching costs, how sensitive its customers are to price and what would let a rival take its customers.",
     qa: [["What are economies of scale?", "Falling average cost per unit as output rises, because fixed costs are spread over more units."], ["What is a network effect?", "A product becoming more valuable to each user as more people use it."], ["What gives a firm pricing power?", "Few close substitutes, a strong brand or switching costs, which make customers less sensitive to price."]],
     src: "Carl Shapiro and Hal Varian, Information Rules; Mankiw, Principles of Economics, firm chapters; Michael Porter, Competitive Strategy" }
  ] },
  { k: "Entrepreneurship and Business Models", les: [
   { lv: "B", m: 60, df: 2, t: "Business model basics: how businesses create and capture value",
     obj: ["Describe the nine blocks of the Business Model Canvas", "Tell revenue models apart: sales, subscription, commission and advertising", "Explain customer segments and value propositions"],
     ex: "Fill in a Business Model Canvas for a business you know well, such as a warung or a delivery app. Then write one risky assumption in each of three blocks and how you could test it cheaply.",
     qa: [["What is a value proposition?", "The benefit a business promises to a customer, and why the customer would choose it."], ["Name two common revenue models.", "Direct sales, subscription, commission, licensing or advertising."], ["Why test assumptions before building a business?", "Cheap tests show whether customers want the product, which reduces the risk of wasting time and money."]],
     src: "Alexander Osterwalder and Yves Pigneur, Business Model Generation; Eric Ries, The Lean Startup; Ministry of Cooperatives and SMEs resources" },
   { lv: "A", m: 75, df: 4, t: "Funding, legal form and scaling a small business in Indonesia",
     obj: ["Compare bootstrapping, loans, KUR, angel and venture funding", "Describe legal forms such as UD, CV, PT and the individual PT", "Plan a scaling step with cash needs and risks"],
     ex: "For a business idea of your choice, list three ways to fund the first Rp50 million with pros, cons and obligations of each. Then compare two legal forms and note licences such as the NIB. Check current rules with an official source and note the date.",
     qa: [["What is bootstrapping?", "Funding a business from your own savings and its revenue, without outside investors."], ["What is a CV compared with a PT?", "A CV is a partnership with active partners who carry unlimited liability, while a PT is a limited liability company."], ["What is the NIB?", "The Business Identification Number issued through Indonesia's online business licensing system, used for business registration."]],
     src: "OSS online licensing system information; OJK and Ministry of Cooperatives and SMEs financing guides; Brad Feld and Jason Mendelson, Venture Deals" }
  ] },
  { k: "Business Strategy and Management", les: [
   { lv: "B", m: 60, df: 2, t: "Management basics: planning, organising, leading and controlling",
     obj: ["Describe the four management functions", "Set goals using SMART and simple priorities", "Explain delegation and span of control"],
     ex: "Take a team or project you know, even a family event. Write a one-page plan: goal, tasks, owners, deadlines and how you will check progress. After the project, note what you would change.",
     qa: [["What are the four classic management functions?", "Planning, organising, leading and controlling."], ["What is delegation?", "Giving someone responsibility and authority for a task while remaining accountable for the result."], ["Why measure progress during a project?", "It shows problems early so plans can change before they become costly."]],
     src: "Peter Drucker, The Effective Executive; Henri Fayol, General and Industrial Management; Harvard Business Review management basics" },
   { lv: "A", m: 75, df: 4, t: "Strategy execution: OKRs, KPIs and managing change",
     obj: ["Write objectives and key results (OKRs)", "Choose KPIs that match strategy", "Describe a model for leading change"],
     ex: "Write one OKR set for your own year: one objective with three measurable key results, plus two KPIs you will track monthly. Then list obstacles and a change plan using Kotter's steps. Review it after 3 months.",
     qa: [["What are OKRs in goal setting?","A goal-setting method with an ambitious objective and a few measurable key results that show progress."], ["What makes a good KPI?", "It is measurable, tied to a goal, within the team's influence and reviewed regularly."], ["Why do many change efforts fail?", "Weak urgency, unclear vision, poor communication or no early wins, which are the problems models such as Kotter's try to address."]],
     src: "John Doerr, Measure What Matters; John Kotter, Leading Change; Robert Kaplan and David Norton, The Balanced Scorecard" }
  ] },
  { k: "Corporate Finance", les: [
   { lv: "B", m: 60, df: 2, t: "What corporate finance is: three decisions and sources of capital",
     obj: ["Name the three corporate finance decisions", "Tell debt from equity and describe an IPO", "Explain the goal of maximising long-term value"],
     ex: "Take a listed company and find how it funds itself: debt, equity and retained profit. Write the debt to equity ratio, one recent financing event and one reason the company chose that source. Use the annual report and note the date.",
     qa: [["What are the three main decisions in corporate finance?", "The investment decision, the financing decision and the dividend or payout decision."], ["What is the difference between debt and equity?", "Debt must be repaid with interest and gives lenders no ownership, while equity gives owners a share of profits and control."], ["What is an IPO?", "An initial public offering, when a company first sells shares to the public and lists on an exchange."]],
     src: "Brealey, Myers and Allen, Principles of Corporate Finance; IDX listing guides; Aswath Damodaran, Applied Corporate Finance" },
   { lv: "A", m: 75, df: 4, t: "Capital structure, payout policy and mergers",
     obj: ["Explain Modigliani-Miller and the trade-off theory", "Compare dividends and buybacks", "Describe how mergers create or destroy value"],
     ex: "Choose a company that paid dividends or bought back shares in the last 3 years. Write why it may have chosen that route, the effect on earnings per share and what the choice signals. Then study one merger and list claimed synergies and whether results matched.",
     qa: [["What does Modigliani-Miller say in its simplest form?", "In perfect markets without taxes or distress costs, capital structure does not change firm value."], ["What does the trade-off theory add?", "Firms balance the tax benefit of debt against the costs of financial distress."], ["Why do many mergers fail to create value for the buyer?", "Buyers may overpay, synergies may not materialise and integration is difficult."]],
     src: "Modigliani and Miller (1958); Brealey, Myers and Allen, Principles of Corporate Finance; Aswath Damodaran, Applied Corporate Finance" }
  ] },
  { k: "Financial Independence and Wealth Building", les: [
   { lv: "B", m: 45, df: 1, t: "What financial independence means and the savings rate",
     obj: ["Define financial independence and different versions of it", "Explain why the savings rate matters more than return at the start", "Calculate your own savings rate"],
     ex: "Compute your savings rate for the last 3 months: amount saved or invested divided by after-tax income. Write what financial independence would mean for you in practice, such as time freedom, and the main obstacle.",
     qa: [["What is the savings rate?", "The share of income that is saved or invested rather than spent."], ["Why does the savings rate matter so much early on?", "At first, the amount you save adds far more to your wealth than investment returns on a small balance."], ["What does financial independence mean?", "Having enough income from assets to cover your living costs, so that work becomes a choice."]],
     src: "Vicki Robin, Your Money or Your Life; Morgan Housel, The Psychology of Money; OJK Sikapi Uangmu materials" },
   { lv: "I", m: 75, df: 3, t: "Independence numbers: the 25x rule, the 4 percent idea and limits",
     obj: ["Calculate a target with the 25 times annual spending rule", "Explain the 4 percent rule and where it comes from", "List its limits: sequence risk, inflation, taxes and local conditions"],
     ex: "Estimate your annual spending in a lean, a normal and a comfortable case. Multiply each by 25 to find a target. Then write three reasons the rule might not fit you, such as higher inflation or a longer life, and what margin you would add.",
     qa: [["What target does the 25 times rule give for yearly spending of Rp120 million?", "Rp3 billion, which means withdrawing 4 percent of it each year."], ["Where does the 4 percent rule come from?", "Studies of US historical data, such as Bengen (1994) and the Trinity study, which found 4 percent sustainable over 30 years in the periods tested."], ["What is sequence of returns risk?", "The danger that poor returns early in retirement, while money is being withdrawn, do lasting damage to the portfolio."]],
     src: "William Bengen (1994) Determining Withdrawal Rates Using Historical Data; Cooley, Hubbard and Walz (1998) Trinity study; Vicki Robin, Your Money or Your Life" },
   { lv: "A", m: 75, df: 4, t: "A wealth-building plan: stages, risks, protection and review",
     obj: ["Outline stages: foundation, growth and preservation", "Plan for risks: income loss, health, inflation and inheritance", "Create a yearly review routine and a long-term plan"],
     ex: "Write a one-page, 10-year wealth plan: income growth, saving rate, allocation, protection (insurance and emergency fund), retirement benefits such as BPJS Ketenagakerjaan and DPLK, and a yearly review. Check current benefit rules with official sources and note the date.",
     qa: [["Why is income growth part of a wealth plan?", "Raising skills and income can add more to wealth early on than investment returns alone."], ["What risks can ruin a wealth plan?", "Job or health shocks without insurance, high-cost debt, concentrated bets, fraud and inflation."], ["Why review a wealth plan every year?", "Life, rules, prices and goals change, so regular review keeps the plan realistic."]],
     src: "BPJS Ketenagakerjaan retirement program information; OJK Sikapi Uangmu materials; Morgan Housel, The Psychology of Money; CFP Board planning resources" }
  ] }
 ]
});
